begin;
alter table dev_v2.t_opr_fin10_factura_proveedor add column if not exists itbis_retenido numeric(12,2) check (itbis_retenido>=0);
alter table dev_v2.t_opr_fin10_factura_proveedor add column if not exists itbis_proporcionalidad numeric(12,2) check (itbis_proporcionalidad>=0);
alter table dev_v2.t_opr_fin10_factura_proveedor add column if not exists itbis_costo numeric(12,2) check (itbis_costo>=0);
alter table dev_v2.t_opr_fin10_factura_proveedor add column if not exists itbis_adelantar numeric(12,2) check (itbis_adelantar>=0);
alter table dev_v2.t_opr_fin10_factura_proveedor add column if not exists itbis_percibido numeric(12,2) check (itbis_percibido>=0);
alter table dev_v2.t_opr_fin10_factura_proveedor add column if not exists retencion_renta numeric(12,2) check (retencion_renta>=0);
alter table dev_v2.t_opr_fin10_factura_proveedor add column if not exists isr_percibido numeric(12,2) check (isr_percibido>=0);
alter table dev_v2.t_opr_fin10_factura_proveedor add column if not exists ncf_modificado varchar(20), add column if not exists fecha_pago date, add column if not exists tipo_retencion_isr varchar(2) check(tipo_retencion_isr ~ '^(0[0-9])$');
update dev_v2.mt_cat_opcion set activo=false where formulario_codigo='FIN10_FACT_PROVEEDOR' and catalogo_codigo='TIPO_COMPRA' and opcion_codigo not in ('01','02','03','04','05','06','07','08','09','10','11');
update dev_v2.mt_cat_opcion set activo=false where formulario_codigo='FIN10_FACT_PROVEEDOR' and catalogo_codigo='TIPO_RETENCION_ISR' and opcion_codigo not in ('00','01','02','03','04','05','06','07','08','09');
update dev_v2.mt_cat_opcion set activo=false where formulario_codigo='FIN10_FACT_PROVEEDOR' and catalogo_codigo='FORMA_PAGO' and opcion_codigo not in ('01','02','03','04','05','06','07');
create or replace function dev_v2.fn_guardar_factura_proveedor(p_cabecera jsonb,p_lineas jsonb default '[]') returns jsonb language plpgsql security invoker set search_path='' as $$
declare r dev_v2.t_opr_fin10_factura_proveedor; nuevo_id integer;
begin
if jsonb_array_length(p_lineas)>0 then raise exception 'Detalle de inventario fuera del alcance'; end if;
if nullif(p_cabecera->>'factura_prov_id','') is not null then raise exception 'Utilice la pantalla de modificación'; end if;
select * into r from jsonb_populate_record(null::dev_v2.t_opr_fin10_factura_proveedor,p_cabecera);
return jsonb_build_object('factura_prov_id',nuevo_id); end $$;

notify pgrst,'reload schema';
commit;
